pf_case('F concurrent email entries create one participant and execution without authenticating the other request',function(){ $p=pf_publish();$r=pf_enrollment_race($p['public']);$open=array_values(array_filter($r,static function($v){return !$v['entry'];}));$entry=array_values(array_filter($r,static function($v){return $v['entry'];}));pe_assert(count($open)===1&&count($entry)===1,'Race '.json_encode($r));$rows=pf_db()->rows(pf_db()->prepare('SELECT id,execution_id FROM '.pf_db()->table('participants').' WHERE study_id=%s',$p['definition']['study']['logical_id']));pe_assert(count($rows)===1&&$rows[0]['execution_id']===$open[0]['execution'],'Duplicate identity');pe_assert(count(pf_intents($open[0]['execution'],'VERIFY_PARTICIPANT'))===2,'Missing reentry verification intent');});
pf_case('F explicit PARTICIPANT_VERIFIED anchor blocks then opens assessment',function(){ $d=pe_definition();foreach($d['nodes'] as &$n)if($n['id']==='E_ASSESSMENT'){$n['schedule']['anchor']='PARTICIPANT_VERIFIED';$n['schedule']['anchor_ref']=null;$n['schedule']['occurrence_selector']=null;}unset($n);$p=pe_publish('simple',false,L\Configuration::apply($d));$f=pf_enroll($p);pe_assert($f['view']['next_action']['kind']==='WAIT','Anchor ignored');$r=pf_runtime()->redeem($p['public'],pf_mint($f,'VERIFY_PARTICIPANT'));pe_assert($r['view']['next_action']['kind']==='OPEN_ASSESSMENT','Verification did not resolve anchor');});
pf_case('F initial future assessment renders WAIT and durable availability intent',function(){ $d=L\Configuration::apply(pe_definition(),array('verification_policy'=>'ALLOW_UNVERIFIED'));foreach($d['nodes'] as &$n)if($n['id']==='E_ASSESSMENT')$n['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'ELAPSED','seconds'=>3600));unset($n);$p=pe_publish('simple',false,$d);$f=pf_enroll($p);pe_assert($f['view']['next_action']['kind']==='WAIT'&&count(pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE'))===1,'Future missing');});
pf_case('F expired target authenticates but cannot reopen despite valid 48h link',function(){ $p=pf_publish('08',array('verification_policy'=>'ALLOW_UNVERIFIED'));$f=pf_enroll($p);$block=$f['view']['next_action']['payload']['assessment_execution_id'];$cap=pf_mint($f,'ASSESSMENT_AVAILABLE',$block);$old=$GLOBALS['pf_now'];$GLOBALS['pf_now']='2026-10-12T14:00:00Z';try{$r=pf_runtime()->redeem($p['public'],$cap);pe_assert($r['view']['snapshot']['instances'][$block]['state']==='EXPIRED'&&$r['view']['next_action']['kind']==='WAIT','Deadline extended');}finally{$GLOBALS['pf_now']=$old;}});
pf_case('F WAIT E1 to E4 cancels E2 E3 intents and old E2 cannot open',function()use(&$waitP,&$waitF,&$oldE2){$waitP=pf_publish('08',array('verification_policy'=>'ALLOW_UNVERIFIED','immediate_availability_policy'=>'SEND'));$waitF=pf_enroll($waitP);$s=$waitF['view']['snapshot'];foreach($s['instances'] as $i)if($i['definition_id']==='E_FOLLOWUP_2')$oldE2=pf_mint($waitF,'VERIFY_PARTICIPANT',$i['id']);pf_dispatch($waitF,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$waitF['view']['next_action']['payload']['assessment_execution_id'],'responses'=>array('Q_RISK'=>9)));$r=pf_runtime()->redeem($waitP['public'],$oldE2);pe_assert($r['view']['next_action']['kind']==='WAIT','Opened old E2');foreach(pf_intents($waitF['access']['execution_id'],'ASSESSMENT_AVAILABLE') as $row){$i=$r['view']['snapshot']['instances'][$row['block_execution_id']];if(in_array($i['definition_id'],array('E_FOLLOWUP_2','E_FOLLOWUP_3'),true))pe_assert($row['state']==='CANCELLED','WAIT offer remains');} });
pf_case('F WAIT expiry advances to real E4 and resume MicroBlock excludes intro',function()use(&$waitP,&$waitF){$old=$GLOBALS['pf_now'];$GLOBALS['pf_now']='2026-10-15T11:00:00Z';try{$r=pf_runtime()->redeem($waitP['public'],pf_mint($waitF));$block=$r['view']['next_action']['payload']['assessment_execution_id'];pe_assert($r['view']['snapshot']['instances'][$block]['definition_id']==='E_FOLLOWUP_4'&&in_array('Q_X',$r['view']['presentation']['pages'][$r['view']['presentation']['page_cursor']],true),'Wrong resume '.Canonical::json(array('next'=>$r['view']['next_action'],'pages'=>$r['view']['presentation'])));pe_assert(isset($r['view']['snapshot']['coverage'][$block]['Q_INTRO']),'Intro not covered');}finally{$GLOBALS['pf_now']=$old;}});
pf_case('F worker suppresses cancelled WAIT target without minting capability',function()use(&$waitF){$s=pf_owner()->view($waitF['access']['execution_id'])['snapshot'];foreach(pf_intents($waitF['access']['execution_id']) as $row)if($row['block_execution_id']!==null&&$s['instances'][$row['block_execution_id']]['definition_id']==='E_FOLLOWUP_2'){$before=count($GLOBALS['m0_mail']);$r=pf_delivery($row);pe_assert($r['success']&&count($GLOBALS['m0_mail'])===$before,'Cancelled sent');pe_assert(pf_db()->row(pf_db()->prepare('SELECT id FROM '.pf_db()->table('access_capabilities').' WHERE intent_id=%s',$row['id']))===null,'Cancelled minted');return;}throw new RuntimeException('No E2 fixture');});
pf_case('F timezone confirmation updates source and cancels only future revisions',function(){ $p=pf_publish('05',array('verification_policy'=>'ALLOW_UNVERIFIED'));$f=pf_enroll($p,null,null,null,'America/Argentina/Buenos_Aires');$before=pf_intents($f['access']['execution_id']);$r=array('action'=>'timezone','command_id'=>'TZ_EXPLICIT','csrf'=>$f['csrf'],'expected_revision'=>$f['view']['revision'],'timezone'=>'Europe/Berlin','confirm_timezone'=>'1');$after=pf_runtime()->handle($p['public'],$f['token'],$r);pe_assert($after['view']['snapshot']['execution']['timezone_source']==='PARTICIPANT_LOCAL','Wrong timezone source');$rows=pf_intents($f['access']['execution_id']);pe_assert(count($rows)>count($before)&&count(array_filter($rows,static function($row){return $row['state']==='CANCELLED'&&$row['cancel_reason']==='SCHEDULE_REVISION_CHANGED';}))>0,'No rescheduling');});
pf_case('F timezone proposal never implicitly changes scientific schedule',function(){ $p=pf_publish();$f=pf_enroll($p);$r=array('action'=>'timezone','command_id'=>'TZ_NO_CONFIRM','csrf'=>$f['csrf'],'expected_revision'=>$f['view']['revision'],'timezone'=>'Europe/Berlin');pe_reject(function()use($p,$f,$r){pf_runtime()->handle($p['public'],$f['token'],$r);},'TIMEZONE_CONFIRMATION_REQUIRED');pe_equal($f['view']['snapshot'],pf_owner()->view($f['access']['execution_id'])['snapshot']);});
pf_case('F invalid browser timezone rejects and missing timezone uses study fallback',function(){ $p=pf_publish();pe_reject(function()use($p){pf_enroll($p,null,null,null,'Mars/NoZone');},'TIMEZONE');$f=pf_enroll($p);pe_assert($f['view']['snapshot']['execution']['timezone_source']==='STUDY_FALLBACK','No fallback source');});
foreach(array('gap'=>array('2027-03-14T05:00:00Z','02:30','2027-03-14T07:30:00Z','03:30 EDT'),'fold'=>array('2026-11-01T04:00:00Z','01:30','2026-11-01T05:30:00Z','01:30 EDT')) as $label=>$case)pf_case('F DST '.$label.' agrees on Block intent and rendered local email without duplicate',function()use($case){$old=$GLOBALS['pf_now'];$GLOBALS['pf_now']=$case[0];try{$d=L\Configuration::apply(pe_definition(),array('verification_policy'=>'ALLOW_UNVERIFIED','immediate_availability_policy'=>'SEND'));$d['timezone']['default']='America/New_York';foreach($d['nodes'] as &$n)if($n['id']==='E_ASSESSMENT')$n['schedule']['temporal_rule']=array('kind'=>'LOCAL_DAY_TIME','day_index'=>1,'time'=>$case[1]);unset($n);$p=pe_publish('simple',false,$d);$f=pf_enroll($p,null,null,null,'America/New_York');$intent=pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE')[0];pe_assert($intent['trigger_at']===P\Database::date($case[2]),'Intent DST differs');$GLOBALS['pf_now']=$case[2];$r=pf_delivery($intent);pe_assert($r['success']&&strpos(end($GLOBALS['m0_mail'])['message'],$case[3])!==false,'Email DST differs');$count=count($GLOBALS['m0_mail']);pf_delivery($intent);pe_assert(count($GLOBALS['m0_mail'])===$count,'DST duplicate');}finally{$GLOBALS['pf_now']=$old;}});
pf_case('F availability deferred until eligible ancestor then remains single logical offer',function(){ $p=pf_publish('03',array('verification_policy'=>'ALLOW_UNVERIFIED','immediate_availability_policy'=>'SEND'));$f=pf_enroll($p);$pre=$f['view']['next_action']['payload']['assessment_execution_id'];$r=pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$pre,'responses'=>array('Q_PRE_1'=>2,'Q_PRE_2'=>2)));$future=array_values(array_filter(pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE'),static function($row){return $row['state']==='PENDING';}))[0];$old=$GLOBALS['pf_now'];$GLOBALS['pf_now']='2026-10-13T11:00:00Z';try{pe_assert(pf_delivery($future)['success'],'Availability failed');$mail=end($GLOBALS['m0_mail']);$r=pf_runtime()->redeem($p['public'],pf_link($mail));pe_assert($r['view']['next_action']['kind']==='OPEN_ASSESSMENT','No direct target');$count=count($GLOBALS['m0_mail']);pf_delivery($future);pe_assert(count($GLOBALS['m0_mail'])===$count,'Offer duplicated');}finally{$GLOBALS['pf_now']=$old;}});
pf_case('F reminder after completion cancels and never delivers',function(){ $p=pf_publish(null,array('verification_policy'=>'ALLOW_UNVERIFIED','immediate_availability_policy'=>'SEND'));$f=pf_enroll($p);$reminder=pf_intents($f['access']['execution_id'],'ASSESSMENT_REMINDER')[0];pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$f['view']['next_action']['payload']['assessment_execution_id'],'responses'=>array('Q_q1'=>'done')));$count=count($GLOBALS['m0_mail']);pf_delivery($reminder);pe_assert(count($GLOBALS['m0_mail'])===$count,'Completed reminder sent');});
