pf_case('F active participant receives configured notices without an opt-out preference',function(){ $p=pf_publish(null,array('verification_policy'=>'ALLOW_UNVERIFIED','immediate_availability_policy'=>'SEND'));$f=pf_enroll($p);$intent=pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE')[0];$count=count($GLOBALS['m0_mail']);pf_delivery($intent);pe_assert(count($GLOBALS['m0_mail'])===$count+1&&pf_owner()->view($f['access']['execution_id'])['snapshot']['execution']['state']==='ACTIVE','Active notice missing');});
pf_case('F worker revalidation observes cancellation after capability generation',function(){ $p=pf_publish();$f=pf_enroll($p);$intent=pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT')[0];$observer=new class($f) extends P\TransitionObserver {private $f;public function __construct($f){$this->f=$f;}public function reached(string $point): void {if($point==='before_delivery_revalidation')pf_db()->transactional(function(){pf_db()->update('participants',array('active'=>0),pf_db()->prepare('id=%s',$this->f['access']['participant_id']));});}};$count=count($GLOBALS['m0_mail']);pf_delivery($intent,$observer);pe_assert(count($GLOBALS['m0_mail'])===$count&&pf_intents($f['access']['execution_id'])[0]['state']==='CANCELLED','Failed revalidation');$caps=pf_db()->rows(pf_db()->prepare('SELECT * FROM '.pf_db()->table('access_capabilities').' WHERE intent_id=%s',$intent['id']));foreach($caps as $cap)pe_assert($cap['revoked_at']!==null,'Mint remained live');});
pf_case('F SMTP accepted crash before SENT permits documented duplicate on retry',function(){ $p=pf_publish();$f=pf_enroll($p);$intent=pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT')[0];$count=count($GLOBALS['m0_mail']);pe_reject(function()use($intent){pf_delivery($intent,new P1DFailure('after_delivery_before_sent'));},'INJECTED');pe_assert(count($GLOBALS['m0_mail'])===$count+1&&pf_intents($f['access']['execution_id'])[0]['state']==='CLAIMED','Lost ambiguity');pf_delivery($intent);pe_assert(count($GLOBALS['m0_mail'])===$count+2&&pf_intents($f['access']['execution_id'])[0]['state']==='SENT','Retry semantics changed');});
pf_case('F existing S2 lease excludes second concurrent connection even when timestamp stale',function(){global $wpdb;$p=pf_publish();$f=pf_enroll($p);$job=pf_intents($f['access']['execution_id'])[0]['queue_job_id'];$wpdb->query($wpdb->prepare('UPDATE `'.$wpdb->prefix.'survey_nudge_jobs` SET scheduled_at=%s WHERE id=%d',current_time('mysql'),$job));pe_assert(EIPSI_Notification_Nudge_Queue_Service::mark_processing($job),'Claim failed');$original=$wpdb;$peer=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$peer->set_prefix($wpdb->prefix);try{$peer->query($peer->prepare('UPDATE `'.$peer->prefix.'survey_nudge_jobs` SET processed_at=%s WHERE id=%d','2000-01-01 00:00:00',$job));$wpdb=$peer;pe_assert(!EIPSI_Notification_Nudge_Queue_Service::mark_processing($job),'Double worker claimed');EIPSI_Notification_Nudge_Queue_Service::recover_stale_processing(100);pe_assert($peer->get_var($peer->prepare('SELECT status FROM `'.$peer->prefix.'survey_nudge_jobs` WHERE id=%d',$job))==='processing','Live lease stolen');}finally{$wpdb=$original;EIPSI_Notification_Nudge_Queue_Service::release_processing($job);$peer->close();}});
