pf_case('F queue SQL failure rolls back scientific admission and credentials',function(){global $wpdb;$p=pf_publish();$entry=pf_runtime()->handle($p['public']);$name='pf_queue_fail_'.bin2hex(random_bytes(4));pe_assert($wpdb->query('CREATE TRIGGER `'.$name.'` BEFORE INSERT ON `'.$wpdb->prefix."survey_nudge_jobs` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='P1F_QUEUE_FAILURE'")!==false,'Trigger failed');try{pe_reject(function()use($p,$entry){pf_runtime()->handle($p['public'],$entry['token'],array('action'=>'enroll','command_id'=>'QUEUE_SQL_FAILURE','csrf'=>$entry['csrf'],'email'=>'queue-failure@example.test'));},'STUDY_ENGINE_DATABASE_ERROR');pe_assert((new L\Identity(pf_db(),pf_clock()))->byEmail($p['definition']['study']['logical_id'],'queue-failure@example.test')===null,'SQL false admission');}finally{$wpdb->query('DROP TRIGGER `'.$name.'`');}});
