pf_case('F SENT availability stays immutable while timezone revises future intents',function(){ $p=pf_publish('04',array('verification_policy'=>'ALLOW_UNVERIFIED','immediate_availability_policy'=>'SEND'));$f=pf_enroll($p);$opportunities=pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE');usort($opportunities,static function($a,$b){return strcmp($a['trigger_at'],$b['trigger_at']);});$intent=$opportunities[0];$old=$GLOBALS['pf_now'];$GLOBALS['pf_now']=str_replace(' ','T',$intent['trigger_at']).'Z';try{pe_assert(pf_delivery($intent)['success'],'Send failed');$view=pf_owner()->view($f['access']['execution_id']);$r=array('action'=>'timezone','command_id'=>'TZ_AFTER_SENT','csrf'=>$f['csrf'],'expected_revision'=>$view['revision'],'timezone'=>'Europe/Berlin','confirm_timezone'=>'1');pf_runtime()->handle($p['public'],$f['token'],$r);$row=pf_db()->row(pf_db()->prepare('SELECT * FROM '.pf_db()->table('notification_intents').' WHERE id=%s',$intent['id']));pe_assert($row['state']==='SENT'&&$row['trigger_at']===$intent['trigger_at'],'SENT rewritten');}finally{$GLOBALS['pf_now']=$old;}});
foreach(array('participant_id','execution_id') as $field)pf_case('F capability corrupted '.$field.' binding fails closed',function()use($field){$p=pf_publish();$a=pf_enroll($p);$b=pf_enroll($p);$cap=pf_mint($a);$value=$field==='participant_id'?$b['access']['participant_id']:$b['access']['execution_id'];pf_db()->transactional(function()use($field,$value,$cap){pf_db()->update('access_capabilities',array($field=>$value),pf_db()->prepare('token_hash=%s',hash('sha256',$cap)));});pe_reject(function()use($p,$cap){pf_runtime()->redeem($p['public'],$cap);},'ACCESS_REQUIRED');});
pf_case('F old schedule revision capability authenticates current NextAction only',function(){ $p=pf_publish('05',array('verification_policy'=>'ALLOW_UNVERIFIED'));$f=pf_enroll($p);foreach($f['view']['snapshot']['instances'] as $i)if($i['definition_id']==='E_EMA'&&$i['state']==='SCHEDULED'){$target=$i['id'];break;}$cap=pf_mint($f,'ASSESSMENT_AVAILABLE',$target);$view=pf_owner()->view($f['access']['execution_id']);pf_dispatch($f,'CHANGE_TIMEZONE',array('timezone'=>'Europe/Berlin'));$r=pf_runtime()->redeem($p['public'],$cap);$current=$r['view']['snapshot'];pe_assert($current['instances'][$target]['schedule_revision']>0,'No revision fixture');pe_assert($r['view']['next_action']['kind']!=='OPEN_ASSESSMENT'||$r['view']['next_action']['payload']['assessment_execution_id']!==$target,'Old target forced traversal');});
pf_case('F multiple longitudinal assessments produce distinct actual Storage journals',function(){ $p=pf_publish('03',array('verification_policy'=>'ALLOW_UNVERIFIED'));$f=pf_enroll($p);$pre=$f['view']['next_action']['payload']['assessment_execution_id'];pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$pre,'responses'=>array('Q_PRE_1'=>3,'Q_PRE_2'=>3)));pf_dispatch($f,'ADVANCE_TIME',array('at'=>'2026-10-13T11:00:00Z'));$view=pf_owner()->view($f['access']['execution_id']);$post=$view['next_action']['payload']['assessment_execution_id'];pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$post,'responses'=>array('Q_POST_1'=>3,'Q_POST_2'=>3)));$j=(new P\SubmissionJournalRepository(pf_db()))->list($f['access']['execution_id']);pe_assert(count($j)===2&&$j[0]['submission_id']!==$j[1]['submission_id']&&$j[0]['local_storage_ref']!==$j[1]['local_storage_ref']&&$j[0]['block_execution_id']!==$j[1]['block_execution_id'],'Assessment collision');});
